-- ABIQ : contenu de départ. Généré par scripts/gen-seed.mjs, ne pas modifier à la main.
-- À exécuter une fois, APRÈS schema.sql, dans Supabase > SQL Editor. Relancer ce script ne modifie pas les pages déjà présentes.
-- Dates de sortie : 1 page(s) ouverte(s) tout de suite, puis une nouvelle chaque dimanche à 6 h (heure d'Abidjan),
-- à partir du dimanche qui suit l'exécution. Elles se modifient ensuite dans Administration > Contenus.

create or replace function pg_temp.abiq_sunday(n int) returns timestamptz language sql as $$
  select (date_trunc('week', now()) + interval '6 days 6 hours'
    + case when date_trunc('week', now()) + interval '6 days 6 hours' <= now() then interval '7 days' else interval '0' end
    + (n - 1) * interval '7 days');
$$;

insert into public.worlds (id, position, title, subtitle) values
  ('m1', 1, 'Les premières promesses', 'Ancien Testament'),
  ('m2', 2, 'La bonne nouvelle', 'Nouveau Testament')
on conflict (id) do nothing;

insert into public.levels (id, world_id, position, age_band, status, release_at, content, last_note, published_at)
values ('noe', 'm1', 1, '6-8', 'published', null, $abiq${"title":"Noé","value":"Fidélité","source":"Genèse 6 à 9","sourceNote":"Histoire racontée pour les 6-8 ans à partir de Genèse 6 à 9 (Bible Louis Segond 1910). Les phrases sont simplifiées ; la référence indique où lire le texte.","mystery":{"intro":"Oh ! Une page du Grand Livre s'est effacée. Quelqu'un se cache dedans. Touche les indices pour le découvrir.","clues":["J'ai construit un très grand bateau en bois.","Des animaux sont entrés avec moi, deux par deux.","Une colombe m'a rapporté une feuille d'olivier."],"guess":{"options":["Moïse","Noé","David"],"correct":1,"hints":{"0":"Ce n'est pas Moïse. Lui, il a traversé la mer à pied sec !","2":"Ce n'est pas David. Lui, c'était un jeune berger qui a vaincu un géant."}},"art":"noe/mystery"},"puzzle":{"art":"noe/puzzle","alt":"L'arche de Noé sur l'eau, avec une girafe, un éléphant, une colombe et un arc-en-ciel.","reveal":"Noé a construit une arche pour sauver sa famille et les animaux."},"story":[{"title":"Un homme qui marchait avec Dieu","ref":"Genèse 6.5-9","art":"noe/s1","text":"Il y a très longtemps, les hommes faisaient beaucoup de mal sur la terre, et Dieu en était triste. Mais Noé était juste : il marchait avec Dieu.","alt":"Noé marche sur un chemin, un bâton à la main, près de ses moutons."},{"title":"Un bateau géant","ref":"Genèse 6.13-22","art":"noe/s2","text":"Dieu prévint Noé : de grandes eaux allaient recouvrir la terre. « Construis une arche, un très grand bateau en bois. » Noé fit tout ce que Dieu lui avait demandé.","alt":"Noé tient un marteau devant la coque de l'arche en construction. Un de ses fils porte une planche."},{"title":"Deux par deux","ref":"Genèse 7.1-16","art":"noe/s3","text":"Noé entra dans l'arche avec sa femme, ses trois fils et leurs femmes. Les animaux entrèrent aussi, deux par deux, un mâle et une femelle. Puis Dieu ferma la porte.","alt":"Des couples d'animaux avancent vers la porte de l'arche, où Noé les attend."},{"title":"Quarante jours de pluie","ref":"Genèse 7.11-24","art":"noe/s4","text":"La pluie tomba pendant quarante jours et quarante nuits. L'eau recouvrit toute la terre, même les montagnes. Mais l'arche flottait, et tous ceux qui étaient dedans étaient à l'abri.","alt":"L'arche flotte sur les vagues sous une forte pluie. Ses fenêtres sont éclairées."},{"title":"La colombe revient","ref":"Genèse 8.1-12","art":"noe/s5","text":"Dieu n'oublia pas Noé. Peu à peu, l'eau baissa. Noé lâcha une colombe. Elle revint le soir avec une feuille d'olivier dans son bec : la terre commençait à sécher !","alt":"Une colombe vole vers Noé avec une feuille d'olivier dans le bec."},{"title":"La promesse de l'arc-en-ciel","ref":"Genèse 8.15 à 9.17","art":"noe/s6","text":"Noé sortit de l'arche avec sa famille et tous les animaux. Dieu promit qu'il n'y aurait plus jamais de déluge pour détruire la terre. Il mit un arc-en-ciel dans les nuages, comme signe de sa promesse.","alt":"La famille de Noé et des animaux sous un grand arc-en-ciel. L'arche est posée sur une montagne."}],"lesson":{"text":"Noé a fait tout ce que Dieu lui avait demandé. Et Dieu a tenu sa promesse.","ref":"Genèse 6.22"},"quiz":[{"id":"q1","type":"choice","short":"L'arche","prompt":"Qu'est-ce que Dieu a demandé à Noé de construire ?","options":["Une grande tour","Une maison en pierre","Une arche, un très grand bateau"],"correct":2,"hints":{"0":"Une tour ne flotte pas sur l'eau ! Il fallait quelque chose qui flotte.","1":"Une maison en pierre coulerait. Il fallait quelque chose qui flotte."},"clue":"Dieu allait envoyer beaucoup d'eau sur la terre. Il fallait quelque chose qui flotte !","explain":"Dieu a demandé à Noé de construire une arche, un très grand bateau en bois.","ref":"Genèse 6.14"},{"id":"q2","type":"choice","short":"Deux par deux","prompt":"Comment les animaux sont-ils entrés dans l'arche ?","options":["Deux par deux","Un par un","Tous en même temps"],"correct":0,"hints":{"1":"Pas tout seuls ! Chaque animal avait quelqu'un avec lui.","2":"Ils sont entrés en petits groupes. Combien dans chaque groupe ?"},"clue":"Les animaux n'étaient pas tout seuls : chacun avait un compagnon avec lui.","explain":"Les animaux sont entrés deux par deux, un mâle et une femelle.","ref":"Genèse 7.9"},{"id":"q3","type":"choice","short":"La colombe","prompt":"Quel oiseau est revenu avec une feuille d'olivier dans son bec ?","options":["Le corbeau","La colombe","L'aigle"],"correct":1,"hints":{"0":"Noé a bien lâché un corbeau, mais ce n'est pas lui qui a rapporté la feuille.","2":"Il n'y a pas d'aigle dans cette histoire. Relis la page 5 si tu veux !"},"clue":"Relis la page 5 de l'histoire : un oiseau est revenu le soir avec une feuille.","explain":"Noé a d'abord lâché un corbeau, puis une colombe. C'est la colombe qui est revenue avec une feuille d'olivier.","ref":"Genèse 8.7-11"},{"id":"q4","type":"order","short":"L'ordre","prompt":"Remets l'histoire dans l'ordre. Touche d'abord ce qui s'est passé en premier.","items":[{"label":"Noé construit l'arche","art":"noe/s2"},{"label":"Il pleut 40 jours","art":"noe/s4"},{"label":"L'arc-en-ciel apparaît","art":"noe/s6"}],"show":[2,0,1],"tries":["Qu'est-ce que Noé a dû faire avant la pluie ? Commence par ça.","Tu as trouvé le début. Qu'est-ce qui arrive juste après ?","Il ne reste qu'une image !"],"clue":"Pour être à l'abri de la pluie, Noé devait d'abord avoir… un bateau !","explain":"D'abord Noé construit l'arche, puis il pleut pendant quarante jours. À la fin, Dieu met l'arc-en-ciel dans les nuages.","ref":"Genèse 6 à 9"},{"id":"q5","type":"choice","short":"L'arc-en-ciel","prompt":"Quel signe Dieu a-t-il donné pour montrer sa promesse ?","options":["Un grand soleil","Une étoile filante","Un arc-en-ciel"],"correct":2,"hints":{"0":"Le soleil était déjà là avant. Dieu a mis quelque chose de nouveau dans les nuages.","1":"Pas une étoile. Ce signe apparaît dans les nuages, avec plein de couleurs."},"clue":"Ce signe apparaît dans le ciel après la pluie, avec plein de couleurs.","explain":"Dieu a mis l'arc-en-ciel dans les nuages. C'est le signe de sa promesse : plus jamais de déluge pour détruire la terre.","ref":"Genèse 9.11-13"}],"card":{"text":"Il a construit l'arche et a fait tout ce que Dieu lui avait demandé.","art":"noe/card","alt":"Noé, une colombe posée sur la main, devant un arc-en-ciel"},"teaser":{"text":"J'ai construit un très grand bateau pour sauver ma famille et les animaux. Qui suis-je ?","art":"noe/teaser"}}$abiq$::jsonb, 'Contenu de départ', now())
on conflict (id) do nothing;

insert into public.levels (id, world_id, position, age_band, status, release_at, content, last_note, published_at)
values ('abraham', 'm1', 2, '6-8', 'published', pg_temp.abiq_sunday(1), $abiq${"title":"Abraham","value":"Confiance","source":"Genèse 12 à 21","sourceNote":"Histoire racontée pour les 6-8 ans à partir de Genèse 12 à 21 (Bible Louis Segond 1910). Les phrases sont simplifiées ; la référence indique où lire le texte. Au début, Abraham et Sara s'appellent Abram et Saraï ; Dieu change leurs noms en Genèse 17.","mystery":{"intro":"Une nouvelle page s'est effacée ! Qui se cache sous le ciel étoilé ? Regarde les indices.","clues":["Dieu m'a demandé de quitter mon pays pour un pays inconnu.","Une nuit, Dieu m'a dit de compter les étoiles du ciel.","À cent ans, j'ai eu un fils qui s'appelait Isaac."],"guess":{"options":["Abraham","Joseph","Pierre"],"correct":0,"hints":{"1":"Ce n'est pas Joseph. Lui, il avait une tunique de plusieurs couleurs !","2":"Ce n'est pas Pierre. Lui, c'était un pêcheur, ami de Jésus."}},"art":"abraham/mystery"},"puzzle":{"art":"abraham/puzzle","alt":"Abraham devant sa tente, la nuit, montre le ciel rempli d'étoiles. Sara, des moutons et un chameau sont près de lui.","reveal":"Abraham a fait confiance à Dieu et il est parti vers un pays inconnu."},"story":[{"title":"Pars vers un nouveau pays","ref":"Genèse 12.1-5","art":"abraham/s1","text":"Dieu dit à Abraham : « Quitte ton pays et va dans le pays que je te montrerai. » Abraham ne savait pas où il allait. Mais il fit confiance à Dieu et il partit, avec Sara, sa femme.","alt":"Abraham et Sara quittent leur maison avec un bâton et un baluchon."},{"title":"Une longue route","ref":"Genèse 12.5-9","art":"abraham/s2","text":"Ils voyagèrent longtemps avec leurs tentes, leurs troupeaux et leurs serviteurs, jusqu'au pays de Canaan. Là, Dieu promit : « Je donnerai ce pays à ta famille. »","alt":"Une caravane avec des chameaux et des moutons traverse le désert."},{"title":"Compte les étoiles","ref":"Genèse 15.1-6","art":"abraham/s3","text":"Abraham et Sara n'avaient pas d'enfant. Une nuit, Dieu dit à Abraham : « Regarde le ciel et compte les étoiles, si tu peux. Ta famille sera aussi nombreuse ! » Abraham crut Dieu.","alt":"Abraham, debout devant sa tente, regarde un ciel rempli d'étoiles."},{"title":"Trois visiteurs","ref":"Genèse 18.1-14","art":"abraham/s4","text":"Un jour, trois visiteurs vinrent près de sa tente. Ils annoncèrent : « L'année prochaine, Sara aura un fils. » Sara se mit à rire, car elle était déjà très âgée. Mais rien n'est impossible pour Dieu.","alt":"Trois visiteurs sont assis sous un arbre près de la tente. Sara écoute à l'entrée."},{"title":"Isaac, l'enfant du rire","ref":"Genèse 21.1-7","art":"abraham/s5","text":"Dieu tint sa promesse : Sara eut un fils. Abraham avait cent ans ! Ils l'appelèrent Isaac, et Sara dit : « Dieu m'a donné de quoi rire de joie. »","alt":"Sara tient le bébé Isaac dans ses bras. Abraham sourit à côté d'elle."}],"lesson":{"text":"Abraham a fait confiance à Dieu sans savoir où il allait. Et Dieu a tenu sa promesse.","ref":"Genèse 15.6"},"quiz":[{"id":"q1","type":"choice","short":"Le départ","prompt":"Qu'est-ce que Dieu a demandé à Abraham ?","options":["De construire un bateau","De quitter son pays","De devenir roi"],"correct":1,"hints":{"0":"Ça, c'était Noé ! Abraham, lui, devait partir en voyage.","2":"Abraham n'est pas devenu roi. Dieu lui a demandé de partir."},"clue":"Relis la page 1 : Dieu lui a parlé d'un nouveau pays.","explain":"Dieu a demandé à Abraham de quitter son pays pour aller dans le pays qu'il lui montrerait.","ref":"Genèse 12.1"},{"id":"q2","type":"choice","short":"Les étoiles","prompt":"Qu'est-ce qu'Abraham devait compter dans le ciel ?","options":["Les nuages","Les étoiles","Les oiseaux"],"correct":1,"hints":{"0":"Pas les nuages ! C'était la nuit.","2":"Pas les oiseaux. Il faisait nuit, et le ciel brillait."},"clue":"C'était la nuit, et le ciel était plein de petites lumières.","explain":"Dieu a dit à Abraham de compter les étoiles : sa famille serait aussi nombreuse.","ref":"Genèse 15.5"},{"id":"q3","type":"choice","short":"Isaac","prompt":"Comment s'appelait le fils d'Abraham et de Sara ?","options":["Isaac","David","Joseph"],"correct":0,"hints":{"1":"David a vécu bien plus tard. Le nom du fils d'Abraham veut dire « il rit ».","2":"Joseph est venu plus tard : c'est l'arrière-petit-fils d'Abraham."},"clue":"Son nom veut dire « il rit ».","explain":"Le fils d'Abraham et de Sara s'appelait Isaac. Son nom veut dire « il rit ».","ref":"Genèse 21.3"},{"id":"q4","type":"order","short":"L'ordre","prompt":"Remets l'histoire dans l'ordre. Touche d'abord ce qui s'est passé en premier.","items":[{"label":"Abraham quitte son pays","art":"abraham/s1"},{"label":"Dieu montre les étoiles","art":"abraham/s3"},{"label":"Isaac est né","art":"abraham/s5"}],"show":[1,2,0],"tries":["Qu'est-ce qu'Abraham a fait tout au début ? Il est parti…","Tu as trouvé le début. Et ensuite, une nuit, Dieu lui a montré quelque chose…","Il ne reste qu'une image !"],"clue":"D'abord le voyage, puis la promesse, et enfin le bébé.","explain":"Abraham part, puis Dieu lui montre les étoiles, et enfin Isaac naît : Dieu a tenu sa promesse.","ref":"Genèse 12 à 21"},{"id":"q5","type":"choice","short":"Le rire de Sara","prompt":"Pourquoi Sara a-t-elle ri ?","options":["Un chameau faisait le clown","Elle était très âgée pour avoir un bébé","Abraham racontait une blague"],"correct":1,"hints":{"0":"Il n'y a pas de chameau clown dans l'histoire !","2":"Ce n'est pas une blague d'Abraham. Pense à ce que les visiteurs ont annoncé."},"clue":"Les visiteurs ont annoncé une nouvelle étonnante pour une dame très âgée.","explain":"Sara a ri parce qu'elle était très âgée et qu'on lui annonçait un bébé. Mais rien n'est impossible pour Dieu.","ref":"Genèse 18.12-14"}],"card":{"text":"Il a quitté son pays en faisant confiance à Dieu.","art":"abraham/card","alt":"Abraham montre les étoiles, un bâton à la main"},"teaser":{"text":"Je suis parti de mon pays sans savoir où j'allais. Dieu m'a promis une famille aussi nombreuse que les étoiles du ciel. Qui suis-je ?","art":"abraham/teaser"}}$abiq$::jsonb, 'Contenu de départ', now())
on conflict (id) do nothing;

insert into public.levels (id, world_id, position, age_band, status, release_at, content, last_note, published_at)
values ('moise', 'm1', 3, '6-8', 'published', pg_temp.abiq_sunday(2), $abiq${"title":"Moïse","value":"Persévérance","source":"Exode 2 à 15","sourceNote":"Histoire racontée pour les 6-8 ans à partir de Exode 2 à 15 (Bible Louis Segond 1910). Les phrases sont simplifiées ; la référence indique où lire le texte.","mystery":{"intro":"Une page du Grand Livre s'est effacée près d'un grand fleuve… Qui se cache dedans ?","clues":["Quand j'étais bébé, on m'a caché dans un panier sur le fleuve.","Dieu m'a parlé depuis un buisson en feu qui ne se consumait pas.","J'ai levé mon bâton, et la mer s'est ouverte en deux."],"guess":{"options":["Jonas","Daniel","Moïse"],"correct":2,"hints":{"0":"Ce n'est pas Jonas. Lui, il a été avalé par un grand poisson !","1":"Ce n'est pas Daniel. Lui, il a été protégé dans la fosse aux lions."}},"art":"moise/mystery"},"puzzle":{"art":"moise/puzzle","alt":"Moïse lève son bâton. La mer s'ouvre et forme deux murs d'eau de chaque côté d'un chemin.","reveal":"Moïse a conduit le peuple de Dieu hors d'Égypte."},"story":[{"title":"Un bébé dans un panier","ref":"Exode 2.1-10","art":"moise/s1","text":"Le pharaon, roi d'Égypte, rendait la vie très dure au peuple d'Israël. Pour protéger son bébé, une maman le cacha dans un panier, parmi les roseaux du fleuve. La fille du pharaon le trouva et l'appela Moïse.","alt":"Un bébé dort dans un panier au milieu des roseaux, au bord du fleuve."},{"title":"Le buisson en feu","ref":"Exode 3.1-12","art":"moise/s2","text":"Quand Moïse fut grand, il gardait des moutons. Un jour, il vit un buisson en feu qui ne se consumait pas. Dieu lui parla : « Va voir le pharaon et fais sortir mon peuple d'Égypte. »","alt":"Moïse, avec ses moutons, regarde un buisson en flammes sur la montagne."},{"title":"Laisse partir mon peuple","ref":"Exode 5.1 à 12.32","art":"moise/s3","text":"Moïse alla voir le pharaon : « Laisse partir mon peuple ! » Le pharaon refusa. Moïse revint encore et encore. Il y eut dix fléaux sur l'Égypte avant que le pharaon dise enfin oui.","alt":"Moïse, son bâton à la main, parle au pharaon assis sur son trône."},{"title":"La mer s'ouvre","ref":"Exode 14.10-22","art":"moise/s4","text":"Le peuple partit, mais l'armée du pharaon le poursuivit. Devant la mer, Moïse leva son bâton. Dieu fit souffler un vent fort, et la mer s'ouvrit. Le peuple traversa à pied sec !","alt":"Le peuple marche sur un chemin sec entre deux murs d'eau. Moïse lève son bâton."},{"title":"Un chant de victoire","ref":"Exode 15.1-21","art":"moise/s5","text":"De l'autre côté de la mer, Moïse et le peuple chantèrent pour remercier Dieu, au son des tambourins. Dieu avait délivré son peuple !","alt":"Le peuple danse et chante avec des tambourins au bord de la mer."}],"lesson":{"text":"Moïse n'a pas abandonné : il est retourné voir le pharaon encore et encore, en comptant sur Dieu.","ref":"Exode 3.12"},"quiz":[{"id":"q1","type":"choice","short":"Le panier","prompt":"Où la maman de Moïse l'a-t-elle caché quand il était bébé ?","options":["Dans un panier sur le fleuve","Dans une grotte","Dans un grand bateau"],"correct":0,"hints":{"1":"Pas dans une grotte. Il y avait de l'eau tout près.","2":"Le grand bateau, c'était l'arche de Noé ! Moïse était tout petit, dans quelque chose de petit."},"clue":"C'était sur l'eau, au bord du fleuve, parmi les roseaux.","explain":"Sa maman l'a caché dans un panier sur le fleuve. La fille du pharaon l'a trouvé.","ref":"Exode 2.3-6"},{"id":"q2","type":"choice","short":"Le buisson","prompt":"Comment Dieu a-t-il parlé à Moïse la première fois ?","options":["Dans un rêve","Depuis un buisson en feu","Par une lettre"],"correct":1,"hints":{"0":"Ce n'était pas un rêve. Moïse était bien réveillé, avec ses moutons.","2":"Pas de lettre ! Il y avait du feu…"},"clue":"Il y avait un feu étonnant : ça brûlait, mais rien ne se consumait.","explain":"Dieu a parlé à Moïse depuis un buisson en feu qui ne se consumait pas.","ref":"Exode 3.2-4"},{"id":"q3","type":"choice","short":"Le pharaon","prompt":"Que demandait Moïse au pharaon ?","options":["De lui donner son palais","De construire une pyramide","De laisser partir le peuple de Dieu"],"correct":2,"hints":{"0":"Moïse ne voulait pas de palais. Il pensait au peuple d'Israël.","1":"Ce n'est pas ça. Le peuple voulait justement arrêter de travailler dur pour le pharaon !"},"clue":"Il répétait toujours la même phrase : « Laisse partir… »","explain":"Moïse demandait au pharaon : « Laisse partir mon peuple ! » Il est revenu encore et encore.","ref":"Exode 5.1"},{"id":"q4","type":"order","short":"L'ordre","prompt":"Remets l'histoire dans l'ordre. Touche d'abord ce qui s'est passé en premier.","items":[{"label":"Moïse bébé dans le panier","art":"moise/s1"},{"label":"Le buisson en feu","art":"moise/s2"},{"label":"La mer s'ouvre","art":"moise/s4"}],"show":[2,0,1],"tries":["Commence par le moment où Moïse était tout petit.","Tu as trouvé le début. Quand il était grand, qu'a-t-il vu en gardant ses moutons ?","Il ne reste qu'une image !"],"clue":"Commence par Moïse bébé, et finis par la grande traversée.","explain":"D'abord le bébé dans le panier, puis le buisson en feu, et enfin la mer qui s'ouvre.","ref":"Exode 2 à 14"},{"id":"q5","type":"choice","short":"La traversée","prompt":"Comment le peuple a-t-il traversé la mer ?","options":["À la nage","En bateau","À pied sec, entre deux murs d'eau"],"correct":2,"hints":{"0":"Pas à la nage ! Dieu a fait quelque chose d'extraordinaire.","1":"Ils n'avaient pas de bateau. Dieu a ouvert un chemin."},"clue":"Dieu a fait souffler un grand vent, et un chemin est apparu au milieu de l'eau.","explain":"Dieu a ouvert la mer : le peuple a traversé à pied sec, avec l'eau comme un mur à droite et à gauche.","ref":"Exode 14.21-22"}],"card":{"text":"Il n'a pas abandonné et a conduit le peuple hors d'Égypte.","art":"moise/card","alt":"Moïse lève son bâton devant la mer"},"teaser":{"text":"On m'a trouvé bébé dans un panier, au bord d'un grand fleuve. Plus tard, j'ai dit au roi : « Laisse partir mon peuple ! » Qui suis-je ?","art":"moise/teaser"}}$abiq$::jsonb, 'Contenu de départ', now())
on conflict (id) do nothing;

insert into public.levels (id, world_id, position, age_band, status, release_at, content, last_note, published_at)
values ('david', 'm1', 4, '6-8', 'published', pg_temp.abiq_sunday(3), $abiq${"title":"David","value":"Courage","source":"1 Samuel 16 et 17","sourceNote":"Histoire racontée pour les 6-8 ans à partir de 1 Samuel 16 et 17 (Bible Louis Segond 1910). Les phrases sont simplifiées ; la référence indique où lire le texte.","mystery":{"intro":"Chut… On entend des moutons. Une page s'est effacée : qui se cache dedans ?","clues":["J'étais le plus jeune de mes frères et je gardais les moutons.","J'ai affronté un géant qui faisait peur à toute l'armée.","Je n'avais qu'une fronde et cinq pierres lisses."],"guess":{"options":["Salomon","David","Samson"],"correct":1,"hints":{"0":"Ce n'est pas Salomon. Lui, il était célèbre pour sa sagesse.","2":"Ce n'est pas Samson. Lui, il était très fort, avec de très longs cheveux."}},"art":"david/mystery"},"puzzle":{"art":"david/puzzle","alt":"Le jeune berger David fait tourner sa fronde face au géant Goliath, dans une vallée.","reveal":"David a eu le courage d'affronter le géant Goliath."},"story":[{"title":"Le plus jeune des frères","ref":"1 Samuel 16.1-13","art":"david/s1","text":"Dieu envoya le prophète Samuel chez Isaï pour choisir un futur roi. Samuel vit les grands frères, mais Dieu lui dit : « Moi, je regarde le cœur. » Il choisit David, le plus jeune, qui gardait les moutons.","alt":"Samuel verse de l'huile sur la tête du jeune David, devant ses grands frères."},{"title":"Un géant nommé Goliath","ref":"1 Samuel 17.1-11","art":"david/s2","text":"L'armée d'Israël faisait face aux Philistins. Leur champion, Goliath, était un géant. Chaque jour, il criait : « Envoyez-moi un homme pour se battre contre moi ! » Tous les soldats avaient peur.","alt":"Le géant Goliath, en armure, crie devant les soldats d'Israël qui ont peur."},{"title":"Je n'ai pas peur","ref":"1 Samuel 17.17-37","art":"david/s3","text":"David vint apporter à manger à ses frères. Il dit au roi Saül : « Je vais me battre contre lui. Dieu m'a protégé du lion et de l'ours, il me protégera aussi. »","alt":"David parle au roi Saül, qui porte une couronne."},{"title":"Cinq pierres lisses","ref":"1 Samuel 17.38-40","art":"david/s4","text":"Saül lui prêta son armure, mais elle était trop lourde. David prit son bâton, sa fronde, et cinq pierres lisses dans le torrent.","alt":"David ramasse des pierres lisses dans un ruisseau."},{"title":"Avec l'aide de Dieu","ref":"1 Samuel 17.45-50","art":"david/s5","text":"David dit à Goliath : « Je viens au nom de l'Éternel. » Il lança une pierre avec sa fronde. La pierre frappa Goliath au front, et le géant tomba par terre !","alt":"Le géant Goliath tombe en arrière. David tient sa fronde."}],"lesson":{"text":"David a eu du courage parce qu'il comptait sur Dieu, pas sur sa propre force.","ref":"1 Samuel 17.45"},"quiz":[{"id":"q1","type":"choice","short":"Le berger","prompt":"Que faisait David avant d'affronter Goliath ?","options":["Il était roi","Il était berger","Il était pêcheur"],"correct":1,"hints":{"0":"Pas encore ! Il deviendra roi plus tard.","2":"Pêcheur, c'était plutôt Pierre. David s'occupait d'animaux."},"clue":"Il s'occupait des moutons de son père.","explain":"David était berger : il gardait les moutons de son père, Isaï.","ref":"1 Samuel 16.11"},{"id":"q2","type":"choice","short":"La peur","prompt":"Pourquoi les soldats d'Israël avaient-ils peur ?","options":["À cause d'un orage","À cause du géant Goliath","À cause d'un lion"],"correct":1,"hints":{"0":"Il n'y avait pas d'orage. Quelqu'un criait chaque jour…","2":"Le lion, c'est David qui l'avait affronté avant, en gardant ses moutons !"},"clue":"Il était immense et criait chaque jour pour défier l'armée.","explain":"Les soldats avaient peur de Goliath, un géant qui les défiait chaque jour.","ref":"1 Samuel 17.4-11"},{"id":"q3","type":"choice","short":"La fronde","prompt":"Qu'a pris David pour affronter Goliath ?","options":["Une épée et un bouclier","L'armure du roi","Une fronde et cinq pierres"],"correct":2,"hints":{"0":"David n'a pas pris d'épée. Il a pris ses affaires de berger.","1":"Il l'a essayée, mais elle était trop lourde !"},"clue":"Il a ramassé quelque chose dans le torrent.","explain":"David a laissé l'armure trop lourde. Il a pris sa fronde et cinq pierres lisses.","ref":"1 Samuel 17.39-40"},{"id":"q4","type":"order","short":"L'ordre","prompt":"Remets l'histoire dans l'ordre. Touche d'abord ce qui s'est passé en premier.","items":[{"label":"Samuel choisit David","art":"david/s1"},{"label":"David prend cinq pierres","art":"david/s4"},{"label":"Goliath tombe","art":"david/s5"}],"show":[1,2,0],"tries":["Commence par le moment où David était encore un simple berger.","Tu as trouvé le début. Avant le combat, qu'a ramassé David ?","Il ne reste qu'une image !"],"clue":"Commence par le choix du futur roi.","explain":"D'abord Samuel choisit David, puis David ramasse cinq pierres, et enfin Goliath tombe.","ref":"1 Samuel 16 et 17"},{"id":"q5","type":"choice","short":"La confiance","prompt":"Sur qui David comptait-il pour gagner ?","options":["Sur ses grands frères","Sur sa grande taille","Sur Dieu"],"correct":2,"hints":{"0":"Ses frères avaient peur, eux aussi !","1":"David était tout petit à côté de Goliath !"},"clue":"Relis la dernière page : David parle au nom de quelqu'un.","explain":"David a dit : « Je viens au nom de l'Éternel. » Il comptait sur Dieu.","ref":"1 Samuel 17.45"}],"card":{"text":"Avec une fronde et sa confiance en Dieu, il a affronté le géant Goliath.","art":"david/card","alt":"Le jeune berger David avec sa fronde et un mouton"},"teaser":{"text":"J'étais le plus petit de mes frères et je gardais les moutons. Un jour, j'ai affronté un géant. Qui suis-je ?","art":"david/teaser"}}$abiq$::jsonb, 'Contenu de départ', now())
on conflict (id) do nothing;

insert into public.levels (id, world_id, position, age_band, status, release_at, content, last_note, published_at)
values ('jesus', 'm2', 5, '6-8', 'published', pg_temp.abiq_sunday(4), $abiq${"title":"Jésus","value":"L'amour de Dieu","source":"Luc 1 et 2, Matthieu 2","sourceNote":"Histoire racontée pour les 6-8 ans à partir de Luc 1 et 2 et de Matthieu 2 (Bible Louis Segond 1910). Les phrases sont simplifiées ; la référence indique où lire le texte.","mystery":{"intro":"Une page toute neuve s'est effacée : celle d'une naissance très spéciale. Qui se cache dedans ?","clues":["Je suis né à Bethléem, une petite ville.","À ma naissance, ma maman m'a couché dans une mangeoire.","Un ange a annoncé ma naissance à des bergers."],"guess":{"options":["Jésus","Jean-Baptiste","Samuel"],"correct":0,"hints":{"1":"Ce n'est pas Jean-Baptiste. C'est un parent de Jésus, né quelques mois avant lui.","2":"Ce n'est pas Samuel. Lui, il est né bien avant, au temps de l'Ancien Testament."}},"art":"jesus/mystery"},"puzzle":{"art":"jesus/puzzle","alt":"Marie et Joseph près du bébé Jésus couché dans une mangeoire, sous un ciel étoilé. Un berger et un agneau les regardent.","reveal":"Jésus est né à Bethléem. Dieu l'a envoyé parce qu'il aime le monde."},"story":[{"title":"La visite de l'ange","ref":"Luc 1.26-38","art":"jesus/s1","text":"Dieu envoya l'ange Gabriel chez Marie, à Nazareth. « Tu vas avoir un fils, et tu l'appelleras Jésus. » Marie répondit : « Je suis la servante du Seigneur. »","alt":"Un ange lumineux parle à Marie dans sa maison."},{"title":"Pas de place à l'hôtellerie","ref":"Luc 2.1-7","art":"jesus/s2","text":"Marie et Joseph durent voyager jusqu'à Bethléem. Il n'y avait pas de place pour eux dans l'hôtellerie. Jésus naquit, et Marie le coucha dans une mangeoire.","alt":"Marie et Joseph veillent sur le bébé Jésus couché dans une mangeoire."},{"title":"Les bergers dans les champs","ref":"Luc 2.8-14","art":"jesus/s3","text":"La nuit, des bergers gardaient leurs troupeaux. Un ange leur apparut : « N'ayez pas peur ! Aujourd'hui, un Sauveur vous est né. » Puis une foule d'anges loua Dieu : « Gloire à Dieu ! »","alt":"Des bergers et leurs moutons regardent un ange lumineux dans le ciel de nuit."},{"title":"Les bergers trouvent Jésus","ref":"Luc 2.15-20","art":"jesus/s4","text":"Les bergers se dépêchèrent d'aller à Bethléem. Ils trouvèrent Marie, Joseph et le bébé couché dans la mangeoire. Ils repartirent en remerciant Dieu.","alt":"Deux bergers et un agneau arrivent près de la mangeoire où dort Jésus."},{"title":"Les mages et l'étoile","ref":"Matthieu 2.1-11","art":"jesus/s5","text":"Des mages venus d'Orient suivirent une étoile. Elle s'arrêta au-dessus de la maison où était l'enfant. Ils lui offrirent de l'or, de l'encens et de la myrrhe.","alt":"Trois mages apportent des cadeaux devant une maison, sous une grande étoile."}],"lesson":{"text":"Dieu nous aime tellement qu'il a envoyé Jésus dans le monde.","ref":"Jean 3.16"},"quiz":[{"id":"q1","type":"choice","short":"Bethléem","prompt":"Dans quelle ville Jésus est-il né ?","options":["Jérusalem","Bethléem","Nazareth"],"correct":1,"hints":{"0":"Pas Jérusalem. C'était une plus petite ville.","2":"Marie et Joseph habitaient à Nazareth, mais ils ont dû voyager…"},"clue":"Marie et Joseph ont dû voyager jusqu'à cette petite ville.","explain":"Jésus est né à Bethléem, où Marie et Joseph avaient dû se rendre.","ref":"Luc 2.4-7"},{"id":"q2","type":"choice","short":"La mangeoire","prompt":"Où Marie a-t-elle couché le bébé Jésus ?","options":["Dans une mangeoire","Dans un lit doré","Dans un panier sur l'eau"],"correct":0,"hints":{"1":"Il n'y avait pas de lit doré. Il n'y avait même pas de place à l'hôtellerie !","2":"Le panier sur l'eau, c'était Moïse bébé !"},"clue":"C'est l'endroit où mangent les animaux.","explain":"Il n'y avait pas de place à l'hôtellerie : Marie a couché Jésus dans une mangeoire.","ref":"Luc 2.7"},{"id":"q3","type":"choice","short":"L'ange","prompt":"Qui a annoncé la naissance de Jésus aux bergers ?","options":["Un roi","Un ange","Un oiseau"],"correct":1,"hints":{"0":"Pas un roi. C'était un messager venu du ciel.","2":"Pas un oiseau ! C'était un messager de Dieu, tout lumineux."},"clue":"Un messager de Dieu, venu du ciel, au milieu de la nuit.","explain":"Un ange est apparu aux bergers : « N'ayez pas peur ! Un Sauveur vous est né. »","ref":"Luc 2.9-11"},{"id":"q4","type":"order","short":"L'ordre","prompt":"Remets l'histoire dans l'ordre. Touche d'abord ce qui s'est passé en premier.","items":[{"label":"L'ange visite Marie","art":"jesus/s1"},{"label":"Jésus est né","art":"jesus/s2"},{"label":"Les mages offrent leurs cadeaux","art":"jesus/s5"}],"show":[2,0,1],"tries":["Commence avant la naissance : quelqu'un est venu voir Marie…","Tu as trouvé le début. Et ensuite, que s'est-il passé à Bethléem ?","Il ne reste qu'une image !"],"clue":"Avant la naissance, la naissance, puis des visiteurs venus de loin.","explain":"D'abord l'ange visite Marie, puis Jésus naît à Bethléem, et enfin les mages apportent leurs cadeaux.","ref":"Luc 1 et 2, Matthieu 2"},{"id":"q5","type":"choice","short":"L'étoile","prompt":"Qu'est-ce qui a guidé les mages jusqu'à Jésus ?","options":["Une carte","Une étoile","Un berger"],"correct":1,"hints":{"0":"Pas de carte ! Ils regardaient le ciel.","2":"Les bergers étaient venus avant. Les mages, eux, regardaient le ciel."},"clue":"Ils regardaient le ciel et suivaient une lumière.","explain":"Les mages ont suivi une étoile qui s'est arrêtée au-dessus de la maison où était Jésus.","ref":"Matthieu 2.9-11"}],"card":{"text":"Dieu a envoyé son Fils Jésus parce qu'il aime le monde.","art":"jesus/card","alt":"Le bébé Jésus endormi dans la mangeoire"},"teaser":{"text":"Je suis né dans une petite ville, et des anges ont loué Dieu pour ma naissance. Qui suis-je ?","art":"jesus/teaser"}}$abiq$::jsonb, 'Contenu de départ', now())
on conflict (id) do nothing;

insert into public.levels (id, world_id, position, age_band, status, release_at, content, last_note, published_at)
values ('garcon', 'm2', 6, '6-8', 'published', pg_temp.abiq_sunday(5), $abiq${"title":"Le garçon aux cinq pains","value":"Générosité","source":"Jean 6.1-13","sourceNote":"Histoire racontée pour les 6-8 ans à partir de Jean 6.1-13 (Bible Louis Segond 1910). Les phrases sont simplifiées ; la référence indique où lire le texte. La Bible ne donne pas le prénom du garçon.","mystery":{"intro":"Une page s'est effacée au milieu d'une immense foule. Qui se cache dedans ?","clues":["J'étais dans une très grande foule venue écouter Jésus.","J'avais apporté un petit repas : cinq pains et deux poissons.","Avec mon repas, Jésus a nourri des milliers de personnes !"],"guess":{"options":["Zachée","Pierre","Le jeune garçon"],"correct":2,"hints":{"0":"Ce n'est pas Zachée. Lui, il est monté dans un arbre !","1":"Ce n'est pas Pierre, l'ami de Jésus. Cherche plutôt un enfant !"}},"art":"garcon/mystery"},"puzzle":{"art":"garcon/puzzle","alt":"Un jeune garçon tend son panier avec cinq pains et deux poissons à Jésus, sur une colline remplie de monde.","reveal":"Le jeune garçon avait cinq pains et deux poissons. Jésus a nourri toute la foule avec !"},"story":[{"title":"Une immense foule","ref":"Jean 6.1-5","art":"garcon/s1","text":"Une grande foule suivait Jésus, car elle voyait les malades qu'il guérissait. Jésus monta sur une colline et vit tout ce monde arriver.","alt":"Une grande foule monte vers Jésus, assis sur une colline."},{"title":"Où trouver du pain ?","ref":"Jean 6.5-7","art":"garcon/s2","text":"Jésus demanda à son disciple Philippe : « Où acheter du pain pour tous ces gens ? » Philippe répondit : « Même avec beaucoup d'argent, il n'y en aurait pas assez ! »","alt":"Jésus parle avec Philippe, qui a l'air inquiet devant la foule."},{"title":"Cinq pains et deux poissons","ref":"Jean 6.8-9","art":"garcon/s3","text":"André, un autre disciple, dit : « Il y a ici un jeune garçon qui a cinq pains d'orge et deux poissons. Mais qu'est-ce que cela pour tant de monde ? »","alt":"André présente à Jésus un jeune garçon qui tient un panier de pains et de poissons."},{"title":"Jésus dit merci","ref":"Jean 6.10-11","art":"garcon/s4","text":"Jésus fit asseoir les gens dans l'herbe. Il prit les pains, remercia Dieu, et les fit distribuer. Il fit de même avec les poissons.","alt":"Jésus lève les pains vers le ciel pour remercier Dieu. Les gens sont assis dans l'herbe."},{"title":"Douze paniers de restes","ref":"Jean 6.12-13","art":"garcon/s5","text":"Tout le monde mangea autant qu'il voulait. Il y avait environ cinq mille hommes ! Avec les morceaux qui restaient, on remplit douze paniers.","alt":"Douze paniers remplis de morceaux de pain, et la foule rassasiée."}],"lesson":{"text":"Le jeune garçon avait peu, mais avec Jésus, ce peu a nourri une foule entière.","ref":"Jean 6.9-11"},"quiz":[{"id":"q1","type":"choice","short":"Le repas","prompt":"Qu'avait le jeune garçon dans son panier ?","options":["Deux pains et cinq poissons","Un panier de fruits","Cinq pains et deux poissons"],"correct":2,"hints":{"0":"Presque ! Mais c'est l'inverse.","1":"Pas de fruits ! Il avait du pain et du poisson."},"clue":"Une main pleine de pains, et deux poissons.","explain":"Le garçon avait cinq pains d'orge et deux poissons.","ref":"Jean 6.9"},{"id":"q2","type":"choice","short":"Le merci","prompt":"Qu'a fait Jésus avant de distribuer le pain ?","options":["Il a compté les gens","Il a remercié Dieu","Il a chanté une chanson"],"correct":1,"hints":{"0":"Il ne les a pas comptés lui-même. Il a d'abord parlé à Dieu…","2":"Ce n'était pas une chanson. Il a dit merci."},"clue":"Il a dit merci, comme on le fait avant de manger.","explain":"Jésus a pris les pains et a remercié Dieu, puis il les a fait distribuer.","ref":"Jean 6.11"},{"id":"q3","type":"choice","short":"Les paniers","prompt":"Combien de paniers de restes a-t-on remplis ?","options":["Douze","Deux","Cinq"],"correct":0,"hints":{"1":"Bien plus que deux ! Il en restait beaucoup.","2":"Plus que cinq ! Autant que les disciples de Jésus."},"clue":"Autant de paniers que de disciples autour de Jésus.","explain":"Avec les morceaux qui restaient, on a rempli douze paniers !","ref":"Jean 6.13"},{"id":"q4","type":"order","short":"L'ordre","prompt":"Remets l'histoire dans l'ordre. Touche d'abord ce qui s'est passé en premier.","items":[{"label":"La foule arrive","art":"garcon/s1"},{"label":"Le garçon a cinq pains","art":"garcon/s3"},{"label":"Douze paniers de restes","art":"garcon/s5"}],"show":[1,2,0],"tries":["Commence par le moment où tout le monde arrive.","Tu as trouvé le début. Et ensuite, qui avait un petit repas ?","Il ne reste qu'une image !"],"clue":"Commence par la foule, finis par les restes.","explain":"D'abord la foule arrive, puis on trouve le garçon et ses cinq pains, et à la fin il reste douze paniers !","ref":"Jean 6.1-13"},{"id":"q5","type":"choice","short":"Le petit don","prompt":"Que nous apprend cette histoire ?","options":["Qu'il faut garder son repas pour soi","Qu'un petit don peut servir à beaucoup","Qu'il faut toujours avoir faim"],"correct":1,"hints":{"0":"Au contraire ! Pense à ce que Jésus a fait avec ce repas.","2":"Ce n'est pas ça. Pense à tous ceux qui ont mangé."},"clue":"Le repas était petit, mais regarde combien de gens ont mangé !","explain":"Le garçon avait peu, mais Jésus a nourri des milliers de personnes avec. Un petit don peut faire beaucoup.","ref":"Jean 6.9-13"}],"card":{"text":"Ses cinq pains et deux poissons ont servi à nourrir une foule.","art":"garcon/card","alt":"Un jeune garçon tient un panier de pains et de poissons"},"teaser":{"text":"J'avais apporté mon petit repas pour aller écouter Jésus. Ce jour-là, il a servi à nourrir une foule entière ! Qui suis-je ?","art":"garcon/teaser"}}$abiq$::jsonb, 'Contenu de départ', now())
on conflict (id) do nothing;

insert into public.levels (id, world_id, position, age_band, status, release_at, content, last_note, published_at)
values ('zachee', 'm2', 7, '6-8', 'published', pg_temp.abiq_sunday(6), $abiq${"title":"Zachée","value":"Pardon","source":"Luc 19.1-10","sourceNote":"Histoire racontée pour les 6-8 ans à partir de Luc 19.1-10 (Bible Louis Segond 1910). Les phrases sont simplifiées ; la référence indique où lire le texte.","mystery":{"intro":"Une page s'est effacée dans la ville de Jéricho. Quelqu'un se cache… peut-être en hauteur ?","clues":["J'étais le chef des collecteurs d'impôts, et j'étais très riche.","J'étais petit, alors je suis monté dans un arbre pour voir Jésus.","Jésus m'a dit : « Aujourd'hui, je dois aller chez toi ! »"],"guess":{"options":["David","Zachée","Noé"],"correct":1,"hints":{"0":"Ce n'est pas David. Lui aussi était petit, mais il a affronté un géant !","2":"Ce n'est pas Noé. Lui, il a construit un bateau !"}},"art":"zachee/mystery"},"puzzle":{"art":"zachee/puzzle","alt":"Zachée est assis dans les branches d'un grand arbre. Jésus, en bas, lève les yeux vers lui. La foule regarde.","reveal":"Zachée est monté dans un arbre pour voir Jésus, et sa vie a changé."},"story":[{"title":"Un homme riche et mal aimé","ref":"Luc 19.1-2","art":"zachee/s1","text":"À Jéricho vivait Zachée, le chef des collecteurs d'impôts. Il était très riche. Les gens ne l'aimaient pas, car il leur prenait souvent trop d'argent.","alt":"Zachée, assis à sa table, compte des pièces d'or. Des gens mécontents le regardent."},{"title":"Grimpé dans un arbre","ref":"Luc 19.3-4","art":"zachee/s2","text":"Zachée voulait voir Jésus, mais il était petit et la foule était trop grande. Alors il courut en avant et grimpa dans un sycomore.","alt":"Zachée grimpe dans un grand arbre, au-dessus de la foule."},{"title":"Zachée, descends vite !","ref":"Luc 19.5-7","art":"zachee/s3","text":"Arrivé sous l'arbre, Jésus leva les yeux : « Zachée, descends vite, aujourd'hui je dois aller chez toi. » Zachée descendit, tout joyeux. Mais les gens murmuraient.","alt":"Jésus lève les yeux vers Zachée, assis dans les branches."},{"title":"Un cœur changé","ref":"Luc 19.8","art":"zachee/s4","text":"Zachée dit à Jésus : « Je donne la moitié de mes biens aux pauvres. Et si j'ai pris trop à quelqu'un, je lui rends quatre fois plus. »","alt":"Zachée, heureux, donne des pièces à une dame pauvre et à son enfant."},{"title":"Jésus est venu chercher","ref":"Luc 19.9-10","art":"zachee/s5","text":"Jésus dit : « Aujourd'hui, le salut est entré dans cette maison. Je suis venu chercher et sauver ceux qui étaient perdus. »","alt":"Jésus et Zachée partagent un repas dans la maison de Zachée."}],"lesson":{"text":"Jésus a accueilli Zachée tel qu'il était. Son amour et son pardon ont changé son cœur.","ref":"Luc 19.10"},"quiz":[{"id":"q1","type":"choice","short":"L'arbre","prompt":"Pourquoi Zachée est-il monté dans un arbre ?","options":["Pour cueillir des fruits","Pour voir Jésus par-dessus la foule","Pour se cacher des gens"],"correct":1,"hints":{"0":"Il n'avait pas faim ! Il voulait voir quelqu'un.","2":"Il ne se cachait pas. Il était petit et voulait voir…"},"clue":"Il était petit, et la foule était grande.","explain":"Zachée était petit : il est monté dans un sycomore pour voir Jésus passer.","ref":"Luc 19.3-4"},{"id":"q2","type":"choice","short":"L'invitation","prompt":"Qu'a dit Jésus à Zachée ?","options":["« Descends vite, je viens chez toi ! »","« Reste dans ton arbre ! »","« Va-t'en, Zachée ! »"],"correct":0,"hints":{"1":"Non ! Jésus voulait passer du temps avec lui.","2":"Jésus n'a pas rejeté Zachée. Au contraire !"},"clue":"Jésus voulait aller dans la maison de Zachée.","explain":"Jésus a dit : « Zachée, descends vite, aujourd'hui je dois aller chez toi. »","ref":"Luc 19.5"},{"id":"q3","type":"choice","short":"Le changement","prompt":"Qu'a décidé Zachée après la visite de Jésus ?","options":["De quitter Jéricho","De garder tout son argent","De donner aux pauvres et de rendre ce qu'il avait pris"],"correct":2,"hints":{"0":"Il n'est pas parti. C'est son cœur qui a changé.","1":"Au contraire ! Son cœur a changé."},"clue":"Il a pensé aux pauvres et aux gens à qui il avait fait du tort.","explain":"Zachée a donné la moitié de ses biens aux pauvres et a rendu quatre fois plus à ceux qu'il avait trompés.","ref":"Luc 19.8"},{"id":"q4","type":"order","short":"L'ordre","prompt":"Remets l'histoire dans l'ordre. Touche d'abord ce qui s'est passé en premier.","items":[{"label":"Zachée monte dans l'arbre","art":"zachee/s2"},{"label":"Jésus l'appelle","art":"zachee/s3"},{"label":"Zachée donne aux pauvres","art":"zachee/s4"}],"show":[2,0,1],"tries":["Commence par le moment où Zachée voulait voir Jésus.","Tu as trouvé le début. Que s'est-il passé quand Jésus est arrivé sous l'arbre ?","Il ne reste qu'une image !"],"clue":"L'arbre, l'appel de Jésus, puis le grand changement.","explain":"D'abord Zachée monte dans l'arbre, puis Jésus l'appelle et va chez lui, et enfin Zachée décide de donner et de rendre.","ref":"Luc 19.1-10"},{"id":"q5","type":"choice","short":"Pourquoi Jésus est venu","prompt":"Pourquoi Jésus est-il venu, d'après ce qu'il a dit ?","options":["Pour devenir riche","Pour chercher et sauver ceux qui étaient perdus","Pour punir Zachée"],"correct":1,"hints":{"0":"Jésus ne cherchait pas l'argent.","2":"Jésus n'est pas venu punir Zachée, mais l'accueillir."},"clue":"Relis la dernière page de l'histoire.","explain":"Jésus a dit qu'il était venu chercher et sauver ceux qui étaient perdus.","ref":"Luc 19.10"}],"card":{"text":"Jésus l'a accueilli, et son cœur a changé.","art":"zachee/card","alt":"Zachée, souriant, assis dans les branches d'un arbre"},"teaser":{"text":"J'étais tout petit, alors je suis monté dans un arbre pour voir passer Jésus. Qui suis-je ?","art":"zachee/teaser"}}$abiq$::jsonb, 'Contenu de départ', now())
on conflict (id) do nothing;

insert into public.levels (id, world_id, position, age_band, status, release_at, content, last_note, published_at)
values ('samaritain', 'm2', 8, '6-8', 'published', pg_temp.abiq_sunday(7), $abiq${"title":"Le bon Samaritain","value":"Amour du prochain","source":"Luc 10.25-37","sourceNote":"Histoire racontée pour les 6-8 ans à partir de Luc 10.25-37 (Bible Louis Segond 1910). Les phrases sont simplifiées ; la référence indique où lire le texte. Cette histoire est une parabole : Jésus l'a racontée pour expliquer qui est notre prochain.","mystery":{"intro":"Une page s'est effacée sur une longue route de montagne. Qui se cache dedans ?","clues":["Je voyageais sur la route qui descend vers Jéricho.","J'ai vu un homme blessé au bord du chemin, et je me suis arrêté.","Je l'ai soigné, puis je l'ai emmené dans une hôtellerie."],"guess":{"options":["Le bon Samaritain","Moïse","Zachée"],"correct":0,"hints":{"1":"Ce n'est pas Moïse. Lui, il a traversé la mer avec le peuple de Dieu.","2":"Ce n'est pas Zachée. Lui, il est monté dans un arbre pour voir Jésus."}},"art":"samaritain/mystery"},"puzzle":{"art":"samaritain/puzzle","alt":"Sur une route de montagne, un Samaritain met un pansement à un homme blessé. Sa monture attend près de lui.","reveal":"Le bon Samaritain s'est arrêté pour aider l'homme blessé."},"story":[{"title":"Qui est mon prochain ?","ref":"Luc 10.25-29","art":"samaritain/s1","text":"Un maître de la loi dit à Jésus : « Il faut aimer son prochain. Mais qui est mon prochain ? » Pour lui répondre, Jésus raconta une histoire.","alt":"Jésus parle avec un maître de la loi, devant un groupe de gens."},{"title":"Un homme blessé","ref":"Luc 10.30","art":"samaritain/s2","text":"Un homme descendait de Jérusalem à Jéricho. Des brigands l'attaquèrent, prirent ses affaires et le laissèrent blessé au bord du chemin.","alt":"Un homme blessé est allongé au bord d'une route, entre les rochers."},{"title":"Ils passent leur chemin","ref":"Luc 10.31-32","art":"samaritain/s3","text":"Un prêtre passa par là. Il vit l'homme, mais il continua sa route. Un autre homme, un Lévite, fit pareil.","alt":"Un prêtre passe de l'autre côté de la route sans s'arrêter."},{"title":"Un Samaritain s'arrête","ref":"Luc 10.33-35","art":"samaritain/s4","text":"Puis un Samaritain arriva. À cette époque, Juifs et Samaritains ne s'entendaient pas. Pourtant, il eut pitié : il soigna l'homme, l'emmena dans une hôtellerie et paya pour qu'on s'occupe de lui.","alt":"Le Samaritain conduit l'homme blessé, installé sur sa monture, jusqu'à l'hôtellerie."},{"title":"Va, et fais de même","ref":"Luc 10.36-37","art":"samaritain/s5","text":"Jésus demanda : « Lequel a été le prochain de l'homme blessé ? » Le maître de la loi répondit : « Celui qui a eu pitié de lui. » Jésus dit : « Va, et toi, fais de même. »","alt":"Jésus sourit et montre le chemin au maître de la loi."}],"lesson":{"text":"Mon prochain, c'est toute personne qui a besoin d'aide, même si elle est différente de moi.","ref":"Luc 10.37"},"quiz":[{"id":"q1","type":"choice","short":"Le conteur","prompt":"Qui a raconté l'histoire du bon Samaritain ?","options":["Moïse","Jésus","David"],"correct":1,"hints":{"0":"Moïse a vécu bien avant. Cette histoire est dans le Nouveau Testament.","2":"Pas David. C'est quelqu'un qui répondait à une question sur le prochain."},"clue":"Il répondait à la question d'un maître de la loi.","explain":"C'est Jésus qui a raconté cette histoire, pour expliquer qui est notre prochain.","ref":"Luc 10.29-30"},{"id":"q2","type":"choice","short":"Ceux qui passent","prompt":"Qu'ont fait le prêtre et le Lévite en voyant l'homme blessé ?","options":["Ils ont continué leur route","Ils l'ont soigné","Ils ont appelé à l'aide"],"correct":0,"hints":{"1":"Non, ce ne sont pas eux qui l'ont soigné !","2":"Ils n'ont appelé personne. Ils sont passés…"},"clue":"Ils l'ont vu… et ils sont passés de l'autre côté.","explain":"Le prêtre et le Lévite ont vu l'homme blessé, mais ils ont continué leur chemin.","ref":"Luc 10.31-32"},{"id":"q3","type":"choice","short":"Le Samaritain","prompt":"Qu'a fait le Samaritain ?","options":["Il a pris les affaires de l'homme","Il a eu peur et s'est enfui","Il a soigné l'homme et pris soin de lui"],"correct":2,"hints":{"0":"Ça, ce sont les brigands qui l'avaient fait !","1":"Non, il n'a pas fui. Il s'est approché."},"clue":"Il s'est approché, et il a eu pitié.","explain":"Le Samaritain a soigné l'homme, l'a emmené dans une hôtellerie et a payé pour qu'on s'occupe de lui.","ref":"Luc 10.33-35"},{"id":"q4","type":"order","short":"L'ordre","prompt":"Remets l'histoire dans l'ordre. Touche d'abord ce qui s'est passé en premier.","items":[{"label":"L'homme est blessé","art":"samaritain/s2"},{"label":"Le prêtre passe son chemin","art":"samaritain/s3"},{"label":"Le Samaritain l'aide","art":"samaritain/s4"}],"show":[2,0,1],"tries":["Commence par ce qui est arrivé à l'homme sur la route.","Tu as trouvé le début. Qui est passé en premier ?","Il ne reste qu'une image !"],"clue":"L'attaque, ceux qui passent, puis celui qui s'arrête.","explain":"D'abord l'homme est attaqué, puis le prêtre passe son chemin, et enfin le Samaritain s'arrête pour le soigner.","ref":"Luc 10.30-35"},{"id":"q5","type":"choice","short":"Le prochain","prompt":"Qui est mon prochain ?","options":["Seulement mes amis","Toute personne qui a besoin d'aide","Seulement les gens de mon pays"],"correct":1,"hints":{"0":"Plus que ça ! Le Samaritain a aidé quelqu'un qu'il ne connaissait pas.","2":"Le Samaritain a aidé un homme qui n'était pas de son peuple !"},"clue":"Le Samaritain a aidé un inconnu, différent de lui.","explain":"Mon prochain, c'est toute personne qui a besoin d'aide. Jésus a dit : « Va, et toi, fais de même. »","ref":"Luc 10.36-37"}],"card":{"text":"Dans l'histoire racontée par Jésus, il a pris soin d'un inconnu blessé.","art":"samaritain/card","alt":"Le bon Samaritain tient une bande de tissu pour soigner"},"teaser":{"text":"Sur la route, j'ai vu un homme blessé que les autres laissaient. Je me suis arrêté pour l'aider. Qui suis-je ?","art":"samaritain/teaser"}}$abiq$::jsonb, 'Contenu de départ', now())
on conflict (id) do nothing;

